properties.Script_1:
// ----------------------------------------------
// Cargar combobox de tipo de documento
// ----------------------------------------------

// Preparar los controles de combobox
//var formulario = theRoot.dataView();
//var separador = formulario.control("SEP");
//var subformulario = separador.form("sygemat_corralon_app/FPG_M_CND_ESP");
var subformulario = theRoot.dataView();

if (subformulario)
{
	var combobox_1 = subformulario.control("DOC_TIP_1");
	var combobox_2 = subformulario.control("DOC_TIP_2");
	var combobox_3 = subformulario.control("DOC_TIP_3");
	var combobox_4 = subformulario.control("DOC_TIP_4");
	var combobox_5 = subformulario.control("DOC_TIP_5");
	var combobox_6 = subformulario.control("DOC_TIP_6");
	var combobox_7 = subformulario.control("DOC_TIP_7");
	var combobox_8 = subformulario.control("DOC_TIP_8");
	var combobox_9 = subformulario.control("DOC_TIP_9");

	combobox_1.clear();
	combobox_2.clear();
	combobox_3.clear();
	combobox_4.clear();
	combobox_5.clear();
	combobox_6.clear();
	combobox_7.clear();
	combobox_8.clear();
	combobox_9.clear();

	// Leer los registros de la tabla
	var lista = new VRegisterList(theRoot);
	lista.setTable("sygemat_corralon_dat/DOC_TIP_M");
	lista.load("NOM", []);
	var numRegistros = lista.size();
	for (var numRegistro = 0; numRegistro < numRegistros; numRegistro++)
	{
		// Leer valores del registro
		var registro = lista.readAt(numRegistro);
		if (registro)
		{
			var nombre = registro.fieldToString("NAME");
			var codigo = registro.fieldToString("ID");

			// Añadir registro a combobox
			combobox_1.addItem(nombre, codigo);
			combobox_2.addItem(nombre, codigo);
			combobox_3.addItem(nombre, codigo);
			combobox_4.addItem(nombre, codigo);
			combobox_5.addItem(nombre, codigo);
			combobox_6.addItem(nombre, codigo);
			combobox_7.addItem(nombre, codigo);
			combobox_8.addItem(nombre, codigo);
			combobox_9.addItem(nombre, codigo);
		};
	};

	// Asignar registro seleccionado al combobox
	combobox_1.setCurrentIndex(combobox_1.findData(theRoot.varToString("DOC_TIP_1")));
	combobox_2.setCurrentIndex(combobox_2.findData(theRoot.varToString("DOC_TIP_2")));
	combobox_3.setCurrentIndex(combobox_3.findData(theRoot.varToString("DOC_TIP_3")));
	combobox_4.setCurrentIndex(combobox_4.findData(theRoot.varToString("DOC_TIP_4")));
	combobox_5.setCurrentIndex(combobox_5.findData(theRoot.varToString("DOC_TIP_5")));
	combobox_6.setCurrentIndex(combobox_6.findData(theRoot.varToString("DOC_TIP_6")));
	combobox_7.setCurrentIndex(combobox_7.findData(theRoot.varToString("DOC_TIP_7")));
	combobox_8.setCurrentIndex(combobox_8.findData(theRoot.varToString("DOC_TIP_8")));
	combobox_9.setCurrentIndex(combobox_9.findData(theRoot.varToString("DOC_TIP_9")));
}
